/// \file restRoot.cxx
/// \brief restRoot: ROOT interactive prompt (TRint) with the REST libraries and macros loaded.
///
/// Usage:
///
///    restRoot [ROOT options] [file.root] [macro.C ...]
///
/// Requires the environment variable REST_PATH (the REST installation). At startup it loads every
/// `$REST_PATH/lib/libRest*.so` (except libRestG4.so), adds `$REST_PATH/include` to the include paths
/// (ACLiC and interpreter), loads the compiled macro libraries `$REST_PATH/macros/lib*_C.so` and declares
/// their functions and global pointers (`$REST_PATH/macros/REST_Macros.h`, generated by CMake), so the
/// REST_* macros can be called directly.
///
/// The arguments that are a REST dataset or run file are removed from the ROOT arguments and the file
/// (the last one, if several, with a warning) is opened with REST_OpenInputFile (globals `_run` and `_ev`,
/// or `_dataSet`). The other arguments (and the program name, argv[0]) are passed to TRint as in `root`.

#include <TInterpreter.h>
#include <TROOT.h>
#include <TRestLogManager.h>
#include <TRestSystemOfUnits.h>
#include <TRestTools.h>
#include <TRint.h>
#include <TStyle.h>
#include <TSystem.h>

#include <algorithm>
#include <filesystem>
#include <iostream>
#include <string>
#include <vector>

namespace {
/// \brief Loads the REST libraries, include path and compiled macros from REST_PATH.
/// \return false if REST_PATH is not set, its lib directory does not exist or no REST library could be
/// loaded; true otherwise (missing macros are reported but not fatal).
bool InitializeRestRuntimeFromRestPath() {
    const char* restPathEnv = gSystem->Getenv("REST_PATH");
    if (!restPathEnv || restPathEnv[0] == '\0') {
        std::cerr << "restRoot: REST_PATH is not set.\n";
        return false;
    }

    const std::filesystem::path restPath(restPathEnv);
    const std::filesystem::path libDir = restPath / "lib";
    const std::filesystem::path includeDir = restPath / "include";

    if (!std::filesystem::exists(libDir) || !std::filesystem::is_directory(libDir)) {
        std::cerr << "restRoot: library directory not found: " << libDir << "\n";
        return false;
    }

    std::vector<std::filesystem::path> libraries;
    for (const auto& entry : std::filesystem::directory_iterator(libDir)) {
        if (!entry.is_regular_file()) continue;
        const auto fileName = entry.path().filename().string();
        if (fileName.rfind("libRest", 0) == 0 && entry.path().extension() == ".so") {
            if (fileName == "libRestG4.so") continue;
            libraries.push_back(entry.path());
        }
    }

    std::sort(libraries.begin(), libraries.end());

    bool loadedAny = false;
    for (const auto& lib : libraries) {
        std::cout << "Loading " << lib << std::endl;
        if (gSystem->Load(lib.string().c_str()) >= 0) {
            loadedAny = true;
        }
    }

    if (!loadedAny) {
        RESTError << "restRoot: no REST shared libraries could be loaded from " << libDir << RESTendl;
        return false;
    }

    if (std::filesystem::exists(includeDir) && std::filesystem::is_directory(includeDir)) {
        // ACLiC and the interpreter
        gSystem->AddIncludePath((" -I" + includeDir.string()).c_str());
        gInterpreter->AddIncludePath(includeDir.string().c_str());
    }

    // The macros are compiled in libraries (lib<macro>_C.so, without dictionary) and REST_Macros.h,
    // generated by CMake, declares their functions and global pointers: loading them is immediate
    // (interpreting all the .C at startup took several seconds). The .C are installed as reference,
    // out of the macro path: .x/.L of them would redefine the declared functions
    const std::filesystem::path macrosDir = restPath / "macros";
    if (std::filesystem::exists(macrosDir) && std::filesystem::is_directory(macrosDir)) {
        std::vector<std::filesystem::path> macroLibraries;
        for (const auto& entry : std::filesystem::directory_iterator(macrosDir)) {
            if (!entry.is_regular_file()) continue;
            const auto fileName = entry.path().filename().string();
            const std::string suffix = "_C.so";
            if (fileName.rfind("lib", 0) == 0 && fileName.size() > suffix.size() &&
                fileName.compare(fileName.size() - suffix.size(), suffix.size(), suffix) == 0) {
                macroLibraries.push_back(entry.path());
            }
        }
        std::sort(macroLibraries.begin(), macroLibraries.end());
        for (const auto& lib : macroLibraries) {
            if (gSystem->Load(lib.string().c_str()) < 0) {
                RESTError << "restRoot: the macro library " << lib << " could not be loaded" << RESTendl;
            }
        }

        const std::filesystem::path declarations = macrosDir / "REST_Macros.h";
        if (!std::filesystem::exists(declarations) ||
            !gInterpreter->Declare(("#include \"" + declarations.string() + "\"").c_str())) {
            RESTError << "restRoot: the macro declarations " << declarations << " could not be loaded"
                      << RESTendl;
        }
    }

    return true;
}

}  // namespace

/// \brief Initializes the REST runtime, opens the REST file of the arguments (if any) and starts the ROOT
/// prompt.
/// \return 1 if the REST runtime cannot be initialized, 0 when the prompt exits.
int main(int argc, char* argv[]) {
    std::cout << "---------------------Welcome to RESTRoot--------------------\n";

    REST_Units::SetGeoManagerDefaultUnits();

    if (!InitializeRestRuntimeFromRestPath()) {
        return 1;
    }

    // argv[0] (the program) is passed to TRint as it is; the REST files are looked for from argv[1]
    std::vector<std::string> restFiles;
    std::vector<char*> cleanArgv;
    if (argc > 0) cleanArgv.push_back(argv[0]);

    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];
        std::string fullPath = TRestTools::GetFullPath(arg);

        if (TRestTools::isDataSet(fullPath) || TRestTools::isValidTRestRun(fullPath)) {
            restFiles.push_back(fullPath);
            continue;
        }

        cleanArgv.push_back(argv[i]);
    }

    // A single REST file is opened (the globals _run, _ev and _dataSet hold one file): the last one
    const std::string fileToOpen = restFiles.empty() ? "" : restFiles.back();
    if (restFiles.size() > 1) {
        RESTWarning << "restRoot: " << restFiles.size() << " REST files given, only the last one is opened ("
                    << fileToOpen << ")" << RESTendl;
    }

    cleanArgv.push_back(nullptr);

    int cleanArgc = static_cast<int>(cleanArgv.size()) - 1;
    char** cleanArgvPtr = cleanArgv.data();

    gStyle->SetPalette(1);
    gStyle->SetTimeOffset(0);

    TRint theApp("App", &cleanArgc, cleanArgvPtr);

    if (!fileToOpen.empty()) {
        std::string command = "REST_OpenInputFile(\"" + fileToOpen + "\");";
        gROOT->ProcessLine(command.c_str());
    }

    theApp.Run();
    return 0;
}
